def resolve_panel(parameters, permitted_panels):
    if not isinstance(parameters, dict):
        raise ValueError("parameters must be a dictionary")
    if (
        not isinstance(permitted_panels, list)
        or not permitted_panels
        or any(not isinstance(item, str) or not item for item in permitted_panels)
        or len(set(permitted_panels)) != len(permitted_panels)
    ):
        raise ValueError("permitted_panels must contain distinct non-empty strings")

    authenticated = bool(parameters.get("signed_in")) and isinstance(parameters.get("user"), str) and bool(parameters["user"])
    if not authenticated:
        return {"screen": "sign_in", "user": None, "menu": []}

    requested = parameters.get("panel")
    selected = requested if isinstance(requested, str) and requested in permitted_panels else permitted_panels[0]
    return {"screen": selected, "user": parameters["user"], "menu": list(permitted_panels)}

